EXPECTED = ["LY-340","LY-342","LY-344","LY-402","LY-403","LY-404","LY-405","LY-406","LY-407","LY-408",
            "LY-411","LY-413","LY-415","LY-416","LY-417","LY-418","LY-421","LY-423","LY-424","LY-425"]
assert sorted(P.keys()) == sorted(EXPECTED), (sorted(P.keys()), EXPECTED)
assert len(P) == 20

total = 0
for cid in EXPECTED:
    d = P[cid]
    rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    path = os.path.join(BASE, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    total += os.path.getsize(path)

# self-verify: reopen each exact file (no glob over predictions dir listing; direct per-id open)
for cid in EXPECTED:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        r = json.load(f)
    assert r["case_id"] == cid and set(r.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
    t = r["trigger"]
    assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}
    assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed"))

cm = sum(1 for c in EXPECTED if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in EXPECTED if P[c]["trigger"]["reserve_used"])
dp = sum(1 for c in EXPECTED if P[c]["trigger"]["disputed"])
print(f"cases={len(EXPECTED)} written=20 changed_main={cm} reserve_used={ru} disputed={dp} total_bytes={total}")
